"""Residentado Médico · lote 4 parte A (infectología: ITU, hepatitis, flujo vaginal, ETS, meningitis, parasitosis y otros)"""
from lote01a import Q
import lote01a
L = []
lote01a.L = L
SAB = "Sabiston Tratado de Cirugía 21.ª ed."
HAR = "Harrison Principios de Medicina Interna 21.ª ed. (2022)"
MAN = "Mandell, Douglas y Bennett Enfermedades Infecciosas 9.ª ed. (2020)"
CDC = "CDC, Sexually Transmitted Infections Treatment Guidelines (MMWR Recomm Rep 2021;70(4))"
ACOG = "ACOG Practice Bulletin N.º 215, Vaginitis in Nonpregnant Patients (Obstet Gynecol 2020)"

Q(a="infectologia", cat="Infecciones urinarias", tema="Infecciones con menor frecuencia de anaerobios", año=2014, ext=False,
  e="¿En cuál de las infecciones, los gérmenes anaerobios se encuentran con menos frecuencia?",
  o=["Partes blandas profundas.", "Maxilofaciales.", "Tracto genital femenino.", "Abscesos uretrales.", "Infecciones urinarias."], k="E",
  c="Los anaerobios forman parte de la flora de la boca, el colon y la vagina, por lo que causan infecciones cuando una barrera mucosa se rompe y hay tejido necrótico con poco oxígeno: abscesos de partes blandas profundas, infecciones maxilofaciales y odontogénicas, enfermedad pélvica inflamatoria y abscesos genitales. En cambio, la infección urinaria no complicada la producen enterobacterias aerobias, sobre todo Escherichia coli (más de 80 %), seguida de Klebsiella, Proteus y, entre los grampositivos, Staphylococcus saprophyticus y Enterococcus. La orina normal es aerobia y los anaerobios casi nunca se aíslan en urocultivo. Si en un paciente con piuria el cultivo habitual sale estéril, se debe pensar en tuberculosis genitourinaria, clamidia o ureaplasma antes que en anaerobios. Perla: el absceso uretral o periuretral sí puede ser polimicrobiano con anaerobios.",
  f=HAR + "; " + MAN + "; IDSA/ESCMID, Guía de cistitis no complicada (2010)")

Q(a="ginecologia", cat="Infecciones ginecológicas", tema="Criterios diagnósticos de vaginosis bacteriana", año=2014, ext=True,
  e="¿Cuál de los siguientes criterios se usa para establecer el diagnóstico de vaginosis bacteriana?",
  o=["Disminución de leucocitos en secreción vaginal, pH vaginal < 4,5 y test de aminas positivo.",
     "Secreción blanquecina adherente a la pared vaginal, pH vaginal < 4,5 y células guía.",
     "pH vaginal < 4,5, test de aminas positivo e identificación de hifas.",
     "Test de aminas positivo, identificación de células guía y pH > 4,5.",
     "Aumento de leucocitos, células clave en frotis vaginal y pH < 4,5."], k="D",
  c="La vaginosis bacteriana es un desequilibrio de la flora vaginal en el que los lactobacilos son desplazados por Gardnerella y anaerobios. Los criterios clínicos de Amsel exigen tres de cuatro hallazgos: secreción homogénea blanquecina que se adhiere a la pared vaginal, pH mayor de 4,5, olor a pescado al añadir KOH (test de aminas) y células clave (guía) en el examen en fresco. La opción D reúne tres de ellos con el pH correcto. Las opciones A, B, C y E fallan porque ponen un pH menor de 4,5, que es normal o propio de la candidiasis, o porque mencionan hifas, que indican cándida, o aumento de leucocitos, que sugiere tricomoniasis o cervicitis; en la vaginosis los leucocitos están ausentes. El estándar de laboratorio es la puntuación de Nugent. Tratamiento: metronidazol 500 mg cada 12 horas por 7 días.",
  f=ACOG + "; " + CDC,
  nota="Enunciado y opciones reconstruidos del OCR (opciones A-E pegadas en el enunciado).")

Q(a="gastroenterologia", cat="Hepatitis virales", tema="Serología de hepatitis B con HBsAg y anti-HBs positivos", año=2014, ext=False,
  e="Mujer de 30 años en un examen de rutina se encuentra HBsAg positivo. Antecedente de pareja sexual consumidor de drogas. Los marcadores para hepatitis B son: anti-HBc IgG positivo, anti-HBs positivo, HBsAg positivo, HBeAg negativo. Con estos resultados se afirma que la paciente presenta hepatitis B...",
  o=["Aguda.", "Curada.", "En período de convalecencia.", "Crónica activa.", "Crónica persistente."], k="C",
  c="En la hepatitis B aguda el primer marcador es el HBsAg, seguido del anti-HBc IgM; cuando el virus se controla, el HBsAg desaparece y aparece el anti-HBs, que marca la inmunidad. Entre ambos hay un período de transición en el que pueden coexistir antígeno y anticuerpo, y el anti-HBc pasa de IgM a IgG; eso corresponde a la convalecencia, por eso la clave es C. Una hepatitis aguda tendría anti-HBc IgM y ningún anti-HBs; una infección curada tendría HBsAg negativo con anti-HBs y anti-HBc positivos; la forma crónica se define por HBsAg persistente más de 6 meses. Perla clínica: la coexistencia de HBsAg y anti-HBs persistente puede verse también en hepatitis crónica con anticuerpos dirigidos a otro subtipo, así que se debe repetir la serología a los 6 meses para confirmar la negativización.",
  f="AASLD, Guía de hepatitis B crónica (2018); " + HAR + "; WHO, Guidelines for hepatitis B (2024)",
  nota="Pregunta ambigua: HBsAg y anti-HBs simultáneos también se describen en hepatitis crónica. Se mantiene la clave del libro (convalecencia).")

Q(a="infectologia", cat="Toxicología", tema="Loxoscelismo cutáneo", año=2014, ext=False,
  e="Ama de casa que al limpiar detrás de cuadros siente un lancetazo en la mano. A las 36 horas presenta hematuria y una placa azulado violácea (placa livedoide). ¿Cuál es el diagnóstico más probable?",
  o=["Loxoscelismo.", "Picadura de escorpión.", "Bothropismo.", "Latrodectismo.", "Picadura de abeja."], k="A",
  c="El loxoscelismo lo causa la mordedura de la araña del rincón (Loxosceles laeta, frecuente en viviendas de Lima y la costa), que se oculta detrás de cuadros y en la ropa. Su veneno contiene esfingomielinasa D, que activa neutrófilos y plaquetas y produce necrosis. La mordedura es poco dolorosa al inicio y a las horas aparece la placa livedoide: zona roja, isquémica pálida y necrótica azulada en una misma lesión. La forma cutáneo-visceral añade hemólisis, hematuria, ictericia y falla renal. El bothropismo (serpiente jergón) produce edema y sangrado local; el latrodectismo (viuda negra) causa dolor muscular y rigidez abdominal; el escorpión, dolor local y manifestaciones autonómicas; la abeja, reacción alérgica. Tratamiento: reposo, analgesia, vigilancia de hemólisis y suero antiloxoscélico en las primeras 24-36 horas.",
  f=HAR + "; Swanson y Vetter, Loxosceles bites (N Engl J Med 2005); MINSA-INS, Norma de manejo de accidentes por animales ponzoñosos",
  nota="Opción C corregida de «Bohotropismo» a «Bothropismo» (OCR). No se verificó en línea el número de la norma MINSA, por eso se cita sin número.")

Q(a="neumologia", cat="Pleura", tema="Neumotórax en tuberculosis pulmonar", año=2014, ext=True,
  e="Paciente de 20 años en tratamiento irregular por tuberculosis pulmonar que súbitamente presenta dolor en hemitórax izquierdo tipo punzada, disnea y shock. ¿Cuál es el diagnóstico más probable?",
  o=["Hemotórax.", "Piotórax.", "Atelectasia masiva.", "Neumotórax.", "Hernia diafragmática."], k="D",
  c="La tuberculosis cavitaria o fibrocaseosa deja lesiones subpleurales que pueden romperse hacia la pleura y producir un neumotórax secundario. La instalación súbita de dolor pleurítico, disnea y colapso hemodinámico indica un neumotórax a tensión: el aire entra en la pleura pero no sale, el mediastino se desplaza, se comprime la vena cava y cae el retorno venoso. Al examen hay hipertimpanismo, ausencia de murmullo vesicular y desviación traqueal. El hemotórax y el piotórax se manifiestan con matidez, el piotórax con fiebre previa; la atelectasia masiva desplaza el mediastino hacia el lado afectado y no causa shock brusco; la hernia diafragmática es rara sin trauma. El tratamiento inmediato es la descompresión con aguja en el segundo espacio intercostal y luego tubo de drenaje, sin esperar la radiografía. Además se debe retomar el esquema antituberculoso.",
  f="ERS/EACTS/ESTS, Guías de neumotórax espontáneo en adultos (Eur J Cardiothorac Surg 2024); MINSA, NTS 221-MINSA/DGIESP-2024 (tuberculosis); ATLS 11.ª ed. (2025)")

Q(a="infectologia", cat="Parasitosis", tema="Contenido del absceso hepático amebiano", año=2014, ext=True,
  e="¿Cuál de las siguientes características macroscópicas tiene el contenido de un absceso hepático amebiano?",
  o=["Cremoso.", "Pardo rojizo.", "Seroso.", "Verdoso.", "Cristal de roca."], k="B",
  c="El absceso hepático amebiano lo origina Entamoeba histolytica, que llega al hígado por la vena porta desde el colon. Los trofozoítos lisan los hepatocitos y el parénquima se licúa sin una verdadera supuración: el contenido es un material espeso de color chocolate, pardo rojizo (se describe como «pasta de anchoas»), formado por hepatocitos necrosados y sangre, con pocos neutrófilos y con las amebas en la pared más que en el centro. En contraste, el absceso piógeno bacteriano contiene pus amarillo cremoso o verdoso y huele mal; el quiste hidatídico contiene líquido claro «en cristal de roca»; y el seroso corresponde a un quiste simple. Suele ser único, en el lóbulo derecho y en varones jóvenes. El tratamiento es metronidazol 500-750 mg cada 8 horas por 7-10 días seguido de un amebicida luminal (paromomicina); el drenaje se reserva para abscesos grandes o que no responden.",
  f=HAR + "; " + MAN + "; WHO, Amoebiasis (Weekly Epidemiological Record)")

Q(a="oftalmo_orl", cat="Oftalmología", tema="Agentes de oftalmía neonatal severa", año=2014, ext=True,
  e="¿Cuáles son los agentes infecciosos que causan con más frecuencia oftalmía neonatal severa?",
  o=["Neisseria gonorrhoeae y Chlamydia trachomatis.", "Haemophilus influenzae y Staphylococcus aureus.", "Streptococcus pneumoniae y enterococo.", "Streptococcus pneumoniae y Neisseria gonorrhoeae.", "Haemophilus influenzae y Neisseria gonorrhoeae."], k="A",
  c="La oftalmía neonatal es la conjuntivitis del recién nacido en los primeros 28 días. Las formas graves se adquieren en el canal del parto por patógenos de transmisión sexual: Neisseria gonorrhoeae, que aparece a los 2 a 5 días con secreción purulenta abundante, edema palpebral y riesgo de perforación corneal y ceguera, y Chlamydia trachomatis, que es la causa infecciosa más frecuente y se presenta entre los 5 y 14 días, con secreción mucopurulenta y posible neumonitis asociada. Staphylococcus, Haemophilus y Streptococcus causan cuadros más leves y tardíos. Ante sospecha de gonococo se trata con ceftriaxona intramuscular o intravenosa en dosis única y se lava el ojo; la clamidia se trata con eritromicina oral 14 días. La profilaxis ocular con eritromicina o povidona yodada reduce el riesgo de la forma gonocócica. Se debe tratar también a la madre y sus parejas.",
  f="AAP, Red Book 2024-2027 (Report of the Committee on Infectious Diseases); Nelson Tratado de Pediatría 22.ª ed. (2024); MINSA, NTS 214-2024 (atención neonatal)")

Q(a="infectologia", cat="ETS", tema="Agente etiológico del chancroide", año=2014, ext=True,
  e="¿Cuál es el agente etiológico del chancroide (chancro blando)?",
  o=["Chlamydia trachomatis.", "Corynebacterium urealyticum.", "Treponema pallidum.", "Haemophilus vaginalis.", "Haemophilus ducreyi."], k="E",
  c="El chancroide o chancro blando lo produce Haemophilus ducreyi, un cocobacilo gramnegativo. Tras una incubación corta (3 a 7 días) aparece una pápula que se convierte en una o varias úlceras dolorosas de bordes socavados y fondo sucio purulento, a diferencia del chancro sifilítico, que es indoloro, de base limpia e indurado. La adenopatía inguinal es dolorosa, generalmente unilateral, y puede fistulizarse formando un bubón. Chlamydia trachomatis (serovares L1-L3) causa el linfogranuloma venéreo, Treponema pallidum la sífilis, y los nombres «Haemophilus vaginalis» (hoy Gardnerella) y Corynebacterium urealyticum no son agentes de úlcera genital. Diagnóstico: clínico y por PCR, descartando sífilis y herpes. Tratamiento: azitromicina 1 g por vía oral en dosis única o ceftriaxona 250 mg intramuscular. El chancroide es un cofactor de la transmisión del VIH.",
  f=CDC + "; " + HAR + "; MINSA, NTS 159-MINSA/2019/DGIESP",
  nota="El enunciado traía texto residual del OCR («E. Stap»); se limpió.")

Q(a="ginecologia", cat="Infecciones ginecológicas", tema="Cervicitis en fresa: tricomoniasis", año=2014, ext=True,
  e="Mujer de 28 años, soltera, sexualmente activa, sin atraso menstrual. Acude por secreción vaginal abundante, mal oliente, con prurito vulvar. Examen ginecológico: eritema vaginal en manchas y colpitis macular (cuello uterino en «fresa»). ¿Cuál es el agente etiológico más probable?",
  o=["Candida albicans.", "Neisseria gonorrhoeae.", "Trichomonas vaginalis.", "Chlamydia trachomatis.", "Gardnerella vaginalis."], k="C",
  c="Trichomonas vaginalis es un protozoo flagelado que se transmite sexualmente. Produce una vaginitis con secreción abundante, amarillo verdosa, espumosa y maloliente, prurito, disuria y dispareunia, y se caracteriza por la colpitis macular o «cuello en fresa», causada por microhemorragias puntiformes. El pH vaginal es mayor de 4,5. El diagnóstico se hace con examen en fresco al ver trofozoítos móviles, aunque la sensibilidad es baja (50-60 %); las pruebas de amplificación de ácidos nucleicos son más sensibles. Candida cursa con prurito y flujo grumoso con pH normal; Gardnerella causa un flujo fluido con olor a pescado y células clave, sin inflamación; gonococo y clamidia producen cervicitis mucopurulenta sin vaginitis florida. Tratamiento: metronidazol 500 mg dos veces al día por 7 días en mujeres, con tratamiento de la pareja. Perla: se asocia a parto pretérmino.",
  f=CDC + "; " + ACOG,
  nota="Enunciado y opciones reconstruidos del OCR (se mezclaron con una pregunta vecina).")

Q(a="oftalmo_orl", cat="Oftalmología", tema="Agente más frecuente de blefaritis", año=2014, ext=False,
  e="¿Cuál es la bacteria que causa blefaritis?",
  o=["Pseudomonas aeruginosa.", "Haemophilus influenzae.", "Streptococcus beta hemolítico.", "Neisseria gonorrhoeae.", "Staphylococcus aureus."], k="E",
  c="La blefaritis es la inflamación crónica del borde palpebral. Se distingue la forma anterior (estafilocócica o seborreica), que afecta pestañas y folículos, de la posterior, que es una disfunción de las glándulas de Meibomio. La anterior estafilocócica es la más frecuente de causa infecciosa y se asocia a Staphylococcus aureus y a estafilococos coagulasa negativos, con costras o «collaretes» alrededor de las pestañas, ardor, prurito, sensación de cuerpo extraño y orzuelos recurrentes. La infestación por Demodex es común y favorece la colonización bacteriana. Pseudomonas, Haemophilus, estreptococos beta hemolíticos y gonococo causan conjuntivitis y úlceras corneales, no blefaritis crónica. El tratamiento se basa en higiene palpebral con compresas tibias y limpieza, y en casos activos pomada de azitromicina o eritromicina; si hay disfunción meibomiana se añade doxiciclina oral o aceite de árbol de té para Demodex.",
  f="Kanski Oftalmología Clínica 9.ª ed. (2020); " + MAN,
  nota="Opciones B-E venían pegadas en una sola línea por el OCR; se separaron. Opción A corregida de «auriginosa».")

Q(a="ginecologia", cat="Infecciones ginecológicas", tema="Flujo espumoso amarillento: tricomoniasis", año=2014, ext=False,
  e="Mujer de 25 años que acude a la consulta por presentar flujo vaginal abundante, espumoso, de color amarillento, con mal olor y prurito leve. ¿Cuál es el agente causal?",
  o=["Trichomonas vaginalis.", "Gardnerella vaginalis.", "Candida albicans.", "Chlamydia trachomatis.", "Neisseria gonorrhoeae."], k="A",
  c="Para diferenciar las causas de flujo vaginal conviene combinar aspecto, olor y pH. La tricomoniasis, por Trichomonas vaginalis, se asocia a flujo amarillo verdoso, espumoso, maloliente y pH mayor de 4,5, con prurito y disuria; la vaginosis bacteriana por Gardnerella da un flujo grisáceo, fluido, con olor a pescado y sin inflamación; la candidiasis, un flujo blanco grumoso «en leche cortada», con prurito intenso y pH menor de 4,5; clamidia y gonococo producen cervicitis mucopurulenta, a menudo asintomática, y no un flujo espumoso. El tratamiento de la tricomoniasis es metronidazol 500 mg cada 12 horas por 7 días en la mujer y 2 g en dosis única en el varón, siempre tratando a la pareja y sugiriendo abstinencia hasta terminar. Perla: la tricomoniasis es una ITS, por lo que se debe tamizar VIH y otras infecciones.",
  f=CDC + "; " + ACOG)

Q(a="gastroenterologia", cat="Hepatitis virales", tema="Hepatitis C aguda con serología mixta", año=2014, ext=False,
  e="Varón de 25 años con ictericia de piel y mucosas precedida de 4 días de fiebre alta. Exámenes: anti-HAV IgG positivo, anti-HBc positivo con anti-HBs positivo, anti-HCV positivo y anti-HDV negativo. ¿Cuál es el tipo de hepatitis que presenta?",
  o=["Hepatitis A.", "Hepatitis B.", "Hepatitis C.", "Hepatitis D.", "Hepatitis E."], k="C",
  c="El problema consiste en leer los marcadores como pasado o presente. El anti-HAV IgG indica exposición antigua o vacunación contra hepatitis A; sólo la IgM señalaría infección aguda. La combinación anti-HBc con anti-HBs positivos y HBsAg no reportado indica hepatitis B resuelta, con inmunidad. El anti-HDV negativo descarta delta, que además requiere HBsAg. Queda el anti-HCV positivo como único dato compatible con la enfermedad actual; en la práctica se confirmaría con ARN del VHC, porque el anticuerpo puede tardar semanas en aparecer y no distingue infección aguda de pasada. La hepatitis E se sospecha en brotes por agua contaminada o en gestantes. La hepatitis C aguda suele ser asintomática; cronifica en cerca de 70-80 % y hoy se cura con antivirales de acción directa durante 8 a 12 semanas.",
  f="AASLD-IDSA, Hepatitis C Guidance 2023 update (Clin Infect Dis 2023); " + HAR,
  nota="Opciones recompuestas (OCR las dejó como «A. B. e.e. D_. D. E.»). Se mantiene la clave del libro.")

Q(a="infectologia", cat="Zoonosis", tema="Agente de la enfermedad por arañazo de gato", año=2014, ext=False,
  e="¿Cuál es el agente etiológico de la enfermedad por arañazo de gato?",
  o=["Bartonella henselae.", "Bordetella pertussis.", "Chlamydia trachomatis.", "Staphylococcus epidermidis.", "Streptococcus pyogenes."], k="A",
  c="La enfermedad por arañazo de gato la produce Bartonella henselae, un bacilo gramnegativo intracelular facultativo cuyo reservorio son los gatos, sobre todo los cachorros, y que se transmite por arañazos, mordeduras o por la pulga del gato. A los 3-14 días aparece una pápula o pústula en el sitio de inoculación y a las 1-3 semanas una linfadenopatía regional dolorosa, con fiebre baja y malestar. Suele ser autolimitada, pero puede dar síndrome oculoglandular de Parinaud, encefalopatía, osteomielitis, y en inmunodeprimidos angiomatosis bacilar y peliosis hepática. El diagnóstico se hace por serología o PCR; la tinción de Warthin-Starry muestra bacilos en la biopsia. Bartonella bacilliformis, en cambio, causa la enfermedad de Carrión, endémica en Perú. El tratamiento es de soporte; en casos graves se usa azitromicina. Las otras opciones no tienen relación con gatos.",
  f=HAR + "; " + MAN + "; AAP, Red Book 2024-2027")

Q(a="gastroenterologia", cat="Pancreatitis", tema="Necrosis pancreática infectada: antibiótico", año=2014, ext=False,
  e="Varón de 35 años con diagnóstico de pancreatitis aguda que luego de 7 días presenta fiebre y leucocitosis. El aspirado con aguja fina de la zona pancreática necrótica muestra polimorfonucleares y bacterias. ¿Cuál es el tratamiento más apropiado?",
  o=["Imipenem-cilastatina.", "Ceftriaxona-clindamicina.", "Ceftazidima-vancomicina.", "Piperacilina-tazobactam.", "Cefepima-cloranfenicol."], k="A",
  c="Tras la primera semana, la necrosis pancreática puede infectarse por translocación de bacterias del colon, con fiebre, leucocitosis y a veces gas en la tomografía. Con cultivo o gram positivo del aspirado, se confirma la necrosis infectada y se indican antibióticos que penetren bien el tejido pancreático: carbapenémicos (imipenem o meropenem), quinolonas combinadas con metronidazol, o en algunos esquemas piperacilina-tazobactam. La opción A es la mejor de las ofrecidas; las cefalosporinas con vancomicina o clindamicina no cubren bien anaerobios y bacilos gramnegativos resistentes y penetran peor, y el cloranfenicol no se usa. La profilaxis antibiótica en pancreatitis sin infección no está recomendada. Se retrasa el desbridamiento 4 semanas hasta que la necrosis se encapsule, con un abordaje escalonado: drenaje percutáneo o endoscópico y luego necrosectomía mínimamente invasiva si no mejora.",
  f="AGA, Clinical Practice Update: Management of Pancreatic Necrosis (Gastroenterology 2020); " + SAB + "; " + HAR)

Q(a="neurologia", cat="Unión neuromuscular", tema="Botulismo: déficit de liberación de acetilcolina", año=2014, ext=False,
  e="¿Cuál de las siguientes entidades se presenta por déficit de acetilcolina en la unión neuromuscular de las terminaciones neurales?",
  o=["Botulismo.", "Miastenia gravis.", "Polimiositis.", "Parálisis periódica hiperkalémica.", "Tétanos."], k="A",
  c="La toxina botulínica, producida por Clostridium botulinum, es una endopeptidasa que corta proteínas SNARE de la terminal presináptica e impide la liberación de acetilcolina, por lo que produce una parálisis flácida descendente simétrica que empieza en los pares craneales (visión borrosa, diplopía, ptosis, disartria, disfagia), con pupilas dilatadas y disautonomía anticolinérgica, sin fiebre ni alteración sensorial. En la miastenia gravis hay anticuerpos contra el receptor postsináptico de acetilcolina, no déficit de liberación; la polimiositis es una miopatía inflamatoria; la parálisis periódica hiperkalémica es un canalopatía del sodio muscular; el tétanos bloquea la liberación de neurotransmisores inhibidores (glicina y GABA) y causa espasmos rígidos. El tratamiento es la antitoxina botulínica equina precoz y soporte ventilatorio; en el lactante se emplea inmunoglobulina humana. Perla: la miel es fuente clásica en lactantes.",
  f=HAR + "; Nelson Tratado de Pediatría 22.ª ed. (2024); " + MAN)

Q(a="infectologia", cat="Meningitis", tema="Meningococo sin respuesta a penicilina: tratamiento", año=2014, ext=False,
  e="Mujer de 25 años con diagnóstico de meningoencefalitis hospitalizada en emergencia. Se inicia tratamiento con penicilina G sódica 2 millones cada 4 horas EV durante 48 horas sin presentar mejoría. El cultivo revela Neisseria meningitidis. ¿Cuál es el antibiótico más adecuado?",
  o=["Cefuroxima.", "Ampicilina-sulbactam.", "Cefoxitina.", "Ceftriaxona.", "Aztreonam."], k="D",
  c="Neisseria meningitidis es un diplococo gramnegativo, causa de meningitis con petequias, púrpura y riesgo de sepsis fulminante (síndrome de Waterhouse-Friderichsen). La cefalosporina de tercera generación ceftriaxona (2 g cada 12 horas) es el tratamiento empírico y definitivo de elección porque atraviesa bien la barrera hematoencefálica y cubre cepas con sensibilidad disminuida a penicilina; la duración es de 5 a 7 días. La cefuroxima de segunda generación tiene peor penetración al líquido cefalorraquídeo y fracasó en meningitis; la cefoxitina y la ampicilina-sulbactam no alcanzan concentraciones fiables en el SNC; el aztreonam no es de primera línea. En el empírico se agrega vancomicina por neumococo resistente y ampicilina si se sospecha Listeria (mayores de 50 años o inmunodeprimidos). Los contactos cercanos reciben profilaxis con ciprofloxacino, rifampicina o ceftriaxona, y se vacuna según esquema.",
  f="IDSA, Practice Guidelines for the Management of Bacterial Meningitis (Clin Infect Dis 2004); ESCMID, Guideline on community-acquired bacterial meningitis (Clin Microbiol Infect 2016); " + HAR,
  nota="Opción C corregida de «Cefoxitima» a cefoxitina.")

Q(a="infectologia", cat="Parasitosis", tema="Geohelmintiasis", año=2015, ext=True,
  e="Se consideran parasitosis transmitidas desde el suelo a...",
  o=["Anquilostomiasis, oxiuriasis.", "Paragonimiasis, trichuriasis.", "Ascaridiasis, trichuriasis.", "Fasciolasis, anquilostomiasis.", "Amebiasis, fasciolasis."], k="C",
  c="Las geohelmintiasis son infecciones por nematodos cuyos huevos o larvas necesitan madurar en el suelo cálido y húmedo antes de ser infectantes: Ascaris lumbricoides, Trichuris trichiura, las uncinarias (Ancylostoma duodenale y Necator americanus) y Strongyloides stercoralis. La opción C reúne dos de ellas (ascaridiasis y trichuriasis), ambas por ingestión de huevos del suelo o de alimentos contaminados. En la opción A, la oxiuriasis (Enterobius) se transmite de persona a persona y se adquiere de las manos y la ropa, sin maduración en el suelo. La paragonimiasis y la fasciolasis se adquieren al comer crustáceos o plantas acuáticas y son trematodos; la amebiasis es protozoaria y se transmite por agua. Albendazol 400 mg en dosis única es el tratamiento de ascaridiasis y trichuriasis (3 días en esta última si la carga es alta), y la desparasitación periódica de escolares es la estrategia de salud pública.",
  f="Jourdan et al., Soil-transmitted helminth infections (Lancet 2018); WHO, Guideline: preventive chemotherapy to control soil-transmitted helminth infections (2017); " + HAR,
  nota="La letra de la clave en el OCR (E) no correspondía al texto del comentario del libro; la respuesta correcta por contenido es C (ascaridiasis, trichuriasis).")

Q(a="infectologia", cat="ETS", tema="Uretritis con secreción purulenta", año=2015, ext=True,
  e="Si una persona antes de orinar elimina pus por la uretra, ¿cuál es el diagnóstico más probable?",
  o=["VIH/SIDA.", "Gonorrea.", "Sífilis.", "Virus del papiloma humano.", "Chancroide."], k="B",
  c="La secreción uretral purulenta, especialmente la que aparece antes de la micción, es la manifestación clásica de la uretritis gonocócica, causada por Neisseria gonorrhoeae, que se presenta con secreción abundante, amarillo verdosa, disuria y a menudo después de 2 a 5 días de un contacto sexual de riesgo. La clamidia produce una uretritis no gonocócica con secreción más escasa y mucoide. El VIH no produce secreción; la sífilis causa un chancro indoloro; el VPH, condilomas; el chancroide, úlcera genital dolorosa. El diagnóstico se basa en la tinción de Gram con diplococos gramnegativos intracelulares y en la prueba de amplificación de ácidos nucleicos. Tratamiento actual: ceftriaxona 500 mg intramuscular en dosis única más tratamiento de la clamidia (doxiciclina 100 mg dos veces al día por 7 días) si no se descarta. Se debe tratar a la pareja y ofrecer pruebas de VIH y sífilis.",
  f=CDC + "; MINSA, NTS 159-MINSA/2019/DGIESP; " + HAR,
  nota="La clave no era legible en el OCR («None»); se asignó por contenido (gonorrea).")

Q(a="ginecologia", cat="Infecciones ginecológicas", tema="Flujo espumoso y cérvix con lesiones puntiformes", año=2015, ext=True,
  e="Mujer de 25 años, promiscua, presenta secreción vaginal en moderada cantidad, amarillenta y espumosa. Al examen: cérvix con lesiones eritematosas puntiformes. ¿Cuál es el posible agente etiológico?",
  o=["Candida albicans.", "Trichomonas vaginalis.", "Gardnerella vaginalis.", "Mobiluncus.", "Herpes genital."], k="B",
  c="Un flujo amarillento espumoso con lesiones eritematosas puntiformes del cuello (cérvix «en fresa») es la presentación típica de la tricomoniasis, ITS producida por el protozoo flagelado Trichomonas vaginalis. Las hemorragias puntiformes se observan a simple vista en cerca de 2 % de los casos y por colposcopia en 45 %. El pH vaginal es mayor de 4,5 y en el fresco se aprecian trofozoítos móviles con abundantes polimorfonucleares. La candidiasis da flujo grumoso y pH normal; Gardnerella y Mobiluncus participan en la vaginosis bacteriana, con flujo fluido, olor a pescado y células clave sin inflamación; el herpes genital produce vesículas y úlceras dolorosas y no un flujo. El tratamiento es metronidazol 500 mg dos veces al día por 7 días en la mujer, con tratamiento simultáneo de la pareja. Se recomienda repetir la prueba a los 3 meses por la alta tasa de reinfección.",
  f=CDC + "; " + ACOG,
  nota="Clave ilegible en el OCR («SIN RESPUESTA»). La opción B del libro decía «Trichomona hominis» (protozoo intestinal no patógeno vaginal); se corrigió a Trichomonas vaginalis, que es la respuesta que se pretendía.")

Q(a="gastroenterologia", cat="Hígado", tema="Causa más frecuente de absceso hepático piógeno", año=2015, ext=True,
  e="¿Cuál es la causa más frecuente de absceso hepático piógeno?",
  o=["Diseminación hematógena.", "Septicemia.", "Diverticulitis.", "Infección biliar ascendente.", "Trauma hepático."], k="D",
  c="El absceso hepático piógeno es una colección bacteriana, generalmente polimicrobiana (E. coli, Klebsiella, anaerobios y estreptococos del grupo milleri). La vía de infección más frecuente es la biliar: obstrucción benigna o maligna del colédoco que lleva a colangitis ascendente, por eso debe buscarse litiasis o tumor. Otras vías son la portal (apendicitis, diverticulitis y enfermedad inflamatoria intestinal, mediante pileflebitis), la arterial o hematógena en bacteriemias y endocarditis, la contigüidad (colecistitis), el trauma y la causa criptogénica. En esta pregunta la diverticulitis es una causa portal menos frecuente, y la septicemia y la diseminación hematógena son menos comunes que la biliar. Clínicamente cursa con fiebre, dolor en hipocondrio derecho y hepatomegalia; el diagnóstico es por ecografía o tomografía. Se trata con drenaje percutáneo y antibióticos por 4 a 6 semanas.",
  f=HAR + "; " + SAB + "; " + MAN,
  nota="Opciones B y C venían pegadas en una línea por el OCR. La clave del libro es D (biliar).")

Q(a="salud_publica", cat="Epidemiología", tema="Causalidad del bacilo tuberculoso", año=2015, ext=True,
  e="¿Qué tipo de relación causal puede establecerse entre el bacilo tuberculoso y la tuberculosis?",
  o=["Necesaria y suficiente.", "Suficiente, pero no necesaria.", "Ni suficiente, ni necesaria.", "Predisponente y necesaria.", "Necesaria, pero no suficiente."], k="E",
  c="En epidemiología una causa es necesaria si la enfermedad no ocurre sin ella, y suficiente si por sí sola siempre produce la enfermedad. Sin Mycobacterium tuberculosis no existe tuberculosis, de modo que el bacilo es una causa necesaria. Pero no es suficiente: se estima que cerca de una cuarta parte de la población mundial está infectada, y sólo 5-10 % de los infectados desarrolla enfermedad activa a lo largo de la vida, según cofactores como VIH, diabetes, desnutrición, tabaquismo, hacinamiento, edad e inmunosupresión. Por lo tanto E es la opción correcta. A exigiría que todo infectado enfermara; B y C son falsas porque el bacilo es indispensable; D mezcla un concepto de factor de riesgo con uno de causalidad. Perla: en el modelo de causas componentes de Rothman, el bacilo es la causa componente necesaria dentro de varios mecanismos suficientes. El diagnóstico de infección latente se hace con PPD o IGRA.",
  f="Rothman, Greenland y Lash, Epidemiología Moderna 3.ª ed.; WHO, Global Tuberculosis Report 2024; MINSA, NTS 221-MINSA/DGIESP-2024",
  nota="Enunciado y opciones reconstruidos del OCR (la opción E quedó truncada: «Necesaria, ...»); se completó como «Necesaria, pero no suficiente».")

Q(a="oftalmo_orl", cat="Otorrinolaringología", tema="Etiología bacteriana de la sinusitis del adulto", año=2015, ext=False,
  e="¿Cuál es el agente causal más frecuente en la sinusitis bacteriana del adulto?",
  o=["Streptococcus pyogenes.", "Staphylococcus aureus.", "Streptococcus pneumoniae.", "Chlamydia pneumoniae.", "Pseudomonas aeruginosa."], k="C",
  c="La rinosinusitis aguda es sobre todo viral (resfrío común); sólo 0,5-2 % se complica con infección bacteriana. Se sospecha bacteriana si hay síntomas persistentes más de 10 días sin mejoría, fiebre alta con secreción purulenta y dolor facial por 3-4 días seguidos, o un empeoramiento después de una mejoría inicial («doble empeoramiento»). Los agentes más frecuentes son Streptococcus pneumoniae, seguido de Haemophilus influenzae y Moraxella catarrhalis. Staphylococcus aureus es menos común y se ve en formas crónicas o posquirúrgicas; Pseudomonas, en inmunodeprimidos y fibrosis quística; Chlamydia pneumoniae es rara; S. pyogenes causa faringitis más que sinusitis. El tratamiento de primera línea es amoxicilina-clavulánico (la IDSA 2012 lo prefiere a amoxicilina sola por la resistencia), con doxiciclina como alternativa; los descongestionantes y los lavados nasales son sintomáticos. La complicación temida es la orbitaria.",
  f="IDSA, Clinical Practice Guideline for Acute Bacterial Rhinosinusitis (Clin Infect Dis 2012); AAO-HNS, Clinical Practice Guideline: Adult Sinusitis (2015); Cummings Otorrinolaringología 7.ª ed. (2020)",
  nota="Enunciado corregido: «¿Cuáles el agente...» y «sinusitis del adulto», se precisó bacteriana (como lo exigen las opciones).")

Q(a="infectologia", cat="Diarreas", tema="Disentería con convulsión: Shigella", año=2015, ext=False,
  e="Varón de 65 años, con T: 38 °C, náuseas, vómitos y deposiciones líquidas con moco, sangre y tenesmo. Estando hospitalizado presenta una convulsión por primera vez. ¿Cuál es el agente causal?",
  o=["Entamoeba histolytica.", "Salmonella.", "Escherichia coli.", "Clostridium perfringens.", "Shigella."], k="E",
  c="La tríada fiebre, deposiciones con moco, sangre y tenesmo define el síndrome disentérico, que en este caso orienta a Shigella, un bacilo gramnegativo con baja dosis infectante que invade la mucosa colónica. Una complicación extraintestinal característica es la convulsión, vinculada con la toxina Shiga, la fiebre alta y los trastornos hidroelectrolíticos (hiponatremia); se ve sobre todo en niños pequeños pero también en ancianos. Otras complicaciones son artritis reactiva, megacolon tóxico y, con S. dysenteriae tipo 1, síndrome urémico hemolítico. Entamoeba causa disentería subaguda y sin fiebre alta; Salmonella no tifoidea, diarrea inflamatoria; E. coli enterohemorrágica, diarrea sanguinolenta sin fiebre; Clostridium perfringens, diarrea acuosa breve. El tratamiento es azitromicina 500 mg por 3 días o ciprofloxacino por 3 días en casos graves, con hidratación; se evitan los antimotilidad.",
  f="IDSA, Infectious Diarrhea Guidelines (2017); " + HAR + "; " + MAN,
  nota="Opciones corregidas de OCR («Shiguella», «Escherichia colie», «Clostridiun perfmgens»).")

Q(a="gastroenterologia", cat="Hepatitis virales", tema="Primer marcador en hepatitis B aguda", año=2015, ext=False,
  e="¿Cuál es el primer marcador que se presenta en hepatitis B?",
  o=["Anti-HBs.", "Anti-HBc.", "HBsAg.", "Anti-HBe.", "Anticuerpo IgM."], k="C",
  c="Tras la exposición al virus de la hepatitis B, el primer marcador que aparece en el suero es el antígeno de superficie (HBsAg), entre 1 y 10 semanas después de la infección y antes de los síntomas, junto al ADN viral y el HBeAg. El anti-HBc IgM aparece al inicio de la clínica y cubre la «ventana inmunológica», cuando el HBsAg ya desapareció y el anti-HBs aún no se detecta. El anti-HBs es el último y señala recuperación o inmunidad vacunal (junto con anti-HBc si hay infección natural; sólo anti-HBs si fue por vacuna). El anti-HBe indica baja replicación viral. En la hepatitis B aguda el HBsAg suele desaparecer antes de 6 meses; si persiste más de 6 meses se define infección crónica. Perla: el anti-HBc IgG total sin IgM, con HBsAg negativo, obliga a descartar hepatitis B oculta antes de inmunosupresión o quimioterapia.",
  f="AASLD, Guía de hepatitis B crónica (2018); WHO, Guidelines for hepatitis B (2024); " + HAR)

Q(a="ciencias_basicas", cat="Farmacología", tema="Toxicidad de los aminoglucósidos sobre el VIII par", año=2015, ext=False,
  e="La disfunción que se desarrolla por efecto tóxico de los aminoglucósidos en el sistema nervioso se presenta a nivel...",
  o=["Coclear y olivar.", "Cerebeloso y vestibular.", "Vestibular y coclear.", "Talámico y cortical.", "Hipotalámico y talámico."], k="C",
  c="Los aminoglucósidos (gentamicina, amikacina, estreptomicina, kanamicina) se acumulan en la perilinfa y endolinfa del oído interno y dañan las células ciliadas por estrés oxidativo, de modo que producen ototoxicidad que compromete al VIII par craneal en sus dos ramas. La vestibulotoxicidad causa vértigo, ataxia, nistagmo y oscilopsia, y es más frecuente con estreptomicina y gentamicina; la cocleotoxicidad produce tinnitus y pérdida auditiva neurosensorial de altas frecuencias, más común con amikacina y kanamicina, y suele ser irreversible. Los efectos sobre cerebelo, tálamo, corteza e hipotálamo no son característicos. La nefrotoxicidad (necrosis tubular aguda) es la otra toxicidad principal, y es reversible. Los factores de riesgo son edad avanzada, dosis acumulada, insuficiencia renal y uso con diuréticos de asa. Se previene con una dosis diaria única y monitorización de niveles y función renal, y el bloqueo neuromuscular es otro efecto raro.",
  f="Goodman y Gilman Bases Farmacológicas de la Terapéutica 14.ª ed. (2023); Katzung Farmacología Básica y Clínica 16.ª ed. (2024)",
  nota="Enunciado limpiado del OCR («disfunción·que», «_ aminoglucósidos»). Se mantiene la clave del libro.")
